def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man working on something")
    if not man_patches: 
        return image_patch

    pieces = []
    for man in man_patches:
        objects = image_patch.find("piece")
        for obj in objects:
            if is_in_front_of(obj, man):
                pieces.append((obj, distance_3d(obj, man)))

    if not pieces: 
        return image_patch

    return min(pieces, key=lambda x: x[1])[0]

